#stage .pt-scene{ position:relative; width:100%; height:100%; }#stage .pt-hook{
  position:absolute; inset:0; z-index:9; display:flex; flex-direction:column;
  align-items:center; justify-content:center; gap:20px; text-align:center;
  background:radial-gradient(circle at 50% 38%, rgba(58,160,255,.16), transparent 60%), #0E1420;
  opacity:0; pointer-events:none; transition:opacity .3s ease;
}#stage .pt-hook.on{ opacity:1; }#stage .pt-hook-tag{ color:var(--accent-1); font-family:var(--font-mono); font-size:20px; font-weight:700; letter-spacing:4px; }#stage .pt-hook-q{ color:#fff; font-size:44px; font-weight:800; line-height:1.28; }#stage .pt-hook-q em{ font-style:normal; color:var(--accent-1); }#stage .pt-hook-row{ display:flex; gap:12px; }#stage .pt-hook-ic{
  width:56px; height:56px; border-radius:14px; display:flex; align-items:center; justify-content:center;
  background:rgba(139,149,167,.08); border:1.5px solid var(--border); color:var(--text-dim);
  font-family:var(--font-mono); font-size:24px; font-weight:700;
  opacity:0; transform:scale(.7);
  transition:opacity .22s ease, transform .22s cubic-bezier(.22,1,.36,1), border-color .22s ease, color .22s ease, background .22s ease;
}#stage .pt-hook-ic.on{ opacity:1; transform:none; }#stage .pt-hook-ic.hit{ border-color:rgba(58,160,255,.5); color:var(--accent-1); background:rgba(58,160,255,.12); }#stage .pt-hook-l2{ color:var(--text-primary); font-size:26px; font-weight:600; line-height:1.4; max-width:760px; opacity:0; transition:opacity .3s ease; }#stage .pt-hook-l2 b{ color:var(--accent-1); }#stage .pt-hook-l2.on{ opacity:1; }#stage .pt-win{
  position:absolute; top:0; left:0; width:992px; height:54px; display:flex; align-items:center; gap:14px;
  padding:0 20px; border-radius:16px 16px 0 0; background:var(--titlebar); border:1px solid #000;
  opacity:0; transform:translateY(-8px); transition:opacity .3s ease, transform .3s ease;
}#stage .pt-win.on{ opacity:1; transform:none; }#stage .pt-win-dots{ display:flex; gap:8px; }#stage .pt-win-dots i{ width:13px; height:13px; border-radius:50%; display:block; }#stage .pt-win-dots i:nth-child(1){ background:#ff5f57; }#stage .pt-win-dots i:nth-child(2){ background:#febc2e; }#stage .pt-win-dots i:nth-child(3){ background:#28c840; }#stage .pt-win-title{ color:var(--text-dim); font-size:19px; font-weight:600; }#stage .pt-progress{
  margin-left:auto; padding:8px 18px; border-radius:100px;
  background:rgba(58,160,255,.14); border:1px solid rgba(58,160,255,.35);
  color:var(--accent-1); font-family:var(--font-mono); font-size:18px; font-weight:700;
}#stage .pt-body{ position:absolute; top:54px; left:0; width:992px; height:970px; }#stage .pt-explorer{
  position:relative; width:428px; padding:18px 14px 30px; border-radius:0 0 0 16px;
  background:var(--editor-sidebar); border:1px solid #000; border-top:none;
  opacity:0; transition:opacity .3s ease;
}#stage .pt-explorer.on{ opacity:1; }#stage .pt-exp-h{
  display:flex; align-items:center; justify-content:space-between; padding:0 6px 14px;
  color:var(--text-dim); font-size:14px; font-weight:700; letter-spacing:1.6px;
}#stage .pt-grp{ display:flex; align-items:center; gap:8px; padding:9px 6px; color:var(--text-primary); font-size:19px; font-weight:700; }#stage .pt-grp svg{ width:15px; height:15px; color:var(--text-dim); }#stage .pt-row{
  position:relative; display:flex; align-items:center; gap:12px; padding:12px 12px 12px 24px;
  margin-bottom:5px; border-radius:10px; box-shadow:inset 3px 0 0 transparent;
  opacity:.5; transition:opacity .3s ease, background .25s ease, box-shadow .25s ease;
}#stage .pt-row.show{ opacity:1; }#stage .pt-row.sel{ background:rgba(58,160,255,.14); box-shadow:inset 3px 0 0 var(--accent-1); }#stage .pt-row.sel .pt-fname{ color:#fff; }#stage .pt-fic{ width:30px; height:30px; border-radius:9px; display:flex; align-items:center; justify-content:center; flex-shrink:0; }#stage .pt-fic svg{ width:17px; height:17px; }#stage .pt-fic.pt-c1{ background:rgba(58,160,255,.16); color:var(--accent-1); }#stage .pt-fic.pt-c2{ background:rgba(34,211,238,.14); color:var(--accent-cyan); }#stage .pt-fic.pt-c3{ background:rgba(240,166,74,.16); color:var(--warn); }#stage .pt-fic.pt-c4{ background:rgba(63,185,80,.16); color:var(--success); }#stage .pt-fname{ color:var(--text-primary); font-family:var(--font-mono); font-size:16px; font-weight:600; line-height:1.3; transition:color .25s ease; }#stage .pt-fname i{ color:var(--text-dim); font-style:normal; }#stage .pt-check{
  margin-left:auto; width:19px; height:19px; color:var(--success); flex-shrink:0;
  opacity:0; transform:scale(.5); transition:opacity .25s ease, transform .25s cubic-bezier(.22,1,.36,1);
}#stage .pt-check.on{ opacity:1; transform:none; }#stage .pt-tip{
  position:absolute; left:460px; width:510px; top:0; padding:26px 28px; border-radius:22px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2));
  border:1.5px solid rgba(58,160,255,.4);
  box-shadow:0 20px 55px rgba(0,0,0,.4), 0 0 0 1px rgba(58,160,255,.12);
  opacity:0; transform:translateX(10px);
  transition:top .5s cubic-bezier(.22,1,.36,1), opacity .3s ease, transform .3s ease;
}#stage .pt-tip.show{ opacity:1; transform:none; }#stage .pt-tip-arrow{
  position:absolute; left:-9px; top:36px; width:16px; height:16px;
  background:var(--bg-panel); border-left:1.5px solid rgba(58,160,255,.4); border-bottom:1.5px solid rgba(58,160,255,.4);
  transform:rotate(45deg);
}#stage .pt-tip-ic{ font-size:36px; line-height:1; margin-bottom:12px; }#stage .pt-tip-label{ color:#fff; font-size:31px; font-weight:800; letter-spacing:-.4px; margin-bottom:9px; }#stage .pt-tip-sub{ color:var(--text-dim); font-size:19px; font-weight:500; line-height:1.42; }

stages.js:
MSD.cls('#pt-win', 'on', false);
MSD.cls('#pt-explorer', 'on', false);
MSD.cls('.pt-row', 'show', false);
MSD.cls('.pt-row', 'sel', false);
MSD.cls('.pt-check', 'on', false);
MSD.cls('#pt-tip', 'show', false);
MSD.cls('#pt-hook', 'on', true);
MSD.hide('.pt-hook-ic');
MSD.cls('.pt-hook-ic', 'hit', false);
MSD.cls('#pt-hook-l2', 'on', false);
MSD.q('#pt-progress-n').textContent = '0';
MSD.qa('.pt-hook-ic').forEach(function(el, i){
  MSD.after(250 + i * 70, function(){ el.classList.add('on'); MSD.sfx.tick(); });
});
MSD.after(850, function(){ MSD.cls('.pt-hook-ic', 'hit', true); MSD.sfx.pop(); });
MSD.after(1100, function(){ MSD.cls('#pt-hook-l2', 'on', true); });
MSD.after(1650, function(){
  MSD.cls('#pt-hook', 'on', false);
  MSD.cls('#pt-win', 'on', true);
  MSD.cls('#pt-explorer', 'on', true);
  MSD.show('.pt-row', 55, true);
  MSD.sfx.whoosh(true);
});

MSD.cls('.pt-row', 'sel', false);
MSD.cls('#pt-row-1', 'sel', true);
var r = MSD.q('#pt-row-1').getBoundingClientRect();
var b = MSD.q('#pt-body').getBoundingClientRect();
MSD.q('#pt-tip').style.top = Math.max(0, r.top - b.top - 22) + 'px';
MSD.cls('#pt-tip', 'show', true);
MSD.q('#pt-tip-ic').textContent = "🧠";
MSD.q('#pt-tip-label').textContent = "Always-on memory";
MSD.q('#pt-tip-sub').textContent = "Attached to every chat request in this repo. No path to reference, nothing to import.";
MSD.cls('#pt-check-1', 'on', true);
MSD.q('#pt-progress-n').textContent = '1';
MSD.after(120, function(){ MSD.sfx.blip(0); MSD.punch('#pt-row-1', 0); });

